/* Fixed regression fixture. This program is authored for tests, never generated by the model. */
#include <assert.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* first_link points to the actual first-data link. Data nodes are heap owned. */
static int remove_first(Node **first_link) {
    if (first_link == NULL || *first_link == NULL)
        return 0;
    Node *removed = *first_link;
    *first_link = removed->next;
    free(removed);
    return 1;
}

static Node *node(int value, Node *next) {
    Node *created = malloc(sizeof *created);
    assert(created != NULL);
    created->value = value;
    created->next = next;
    return created;
}

int main(void) {
    Node *first = NULL;
    Node sentinel = { -1, NULL };
    assert(remove_first(&first) == 0);
    assert(remove_first(&sentinel.next) == 0);

    first = node(1, node(2, NULL));
    assert(remove_first(&first) == 1 && first->value == 2);
    assert(remove_first(&first) == 1 && first == NULL);
    assert(remove_first(&first) == 0);

    sentinel.next = node(1, node(2, NULL));
    assert(remove_first(&sentinel.next) == 1 && sentinel.next->value == 2);
    assert(remove_first(&sentinel.next) == 1 && sentinel.next == NULL);
    assert(sentinel.value == -1);
    assert(remove_first(&sentinel.next) == 0);
    return 0;
}
